from collections import Counter,deque

def detect(grid, thresh=.65, minarea=4):
    H,W=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); rects=[]
    for r in range(H):
      for c in range(W):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); pts=[]
        while q:
          y,x=q.pop(); pts.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<H and 0<=xx<W and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        r0=min(y for y,x in pts);r1=max(y for y,x in pts);c0=min(x for y,x in pts);c1=max(x for y,x in pts)
        area=(r1-r0+1)*(c1-c0+1); density=len(pts)/area
        if area>=minarea and r1>r0 and c1>c0 and density>=thresh:
          rects.append((color,r0,r1,c0,c1,len(pts),density))
    out=[[bg]*W for _ in range(H)]
    for color,r0,r1,c0,c1,n,d in rects:
      for y in range(r0,r1+1):
        for x in range(c0,c1+1):out[y][x]=color
    return out,bg,rects
